import { Inter, Noto_Sans_KR } from "next/font/google";

export const inter = Inter({
  weight: ["400", "500", "600", "700"],
  subsets: ["latin"],
  variable: "--font-inter",
  display: "swap",
});

export const notoSansKR = Noto_Sans_KR({
  weight: ["400", "500", "700"],
  subsets: ["latin"],
  variable: "--font-noto-sans-kr",
  display: "swap",
});

"use client";

import { useSyncExternalStore } from "react";

const QUERY = "(prefers-reduced-motion: reduce)";

function subscribe(onChange: () => void): () => void {
  const mql = window.matchMedia(QUERY);
  mql.addEventListener("change", onChange);
  return () => mql.removeEventListener("change", onChange);
}

function getSnapshot(): boolean {
  return window.matchMedia(QUERY).matches;
}

function getServerSnapshot(): boolean {
  return false;
}

/**
 * True when the OS asks for reduced motion.
 * SSR-safe: the server snapshot is `false`; on the client the real value is
 * read synchronously, and live changes to the setting re-render immediately.
 */
export function usePrefersReducedMotion(): boolean {
  return useSyncExternalStore(subscribe, getSnapshot, getServerSnapshot);
}

"use client";

import { useEffect, useRef } from "react";
import { usePrefersReducedMotion } from "./usePrefersReducedMotion";

/**
 * Direction-aware clip-path reveal.
 *
 * Attach the returned ref to a block you want wiped in by a hard geometric
 * cut (the brutalist equivalent of a fade). When the block enters the
 * viewport, `is-revealed` is added to it; `styles.css` drives the
 * inset/polygon clip from `--rave-reveal-dir`. The reveal happens once and
 * the observer disconnects — a section does not get to re-wipe every time
 * it scrolls back into frame.
 *
 * No-JS / SSR: the page ships already visible (`rave-reveal` with no
 * `rave-js` ancestor is static, clip-path: none). The pre-reveal hidden
 * state is gated behind `.rave-js .rave-reveal` so the SSR markup is the
 * completed flyer.
 */
export function useReveal<T extends HTMLElement = HTMLElement>() {
  const ref = useRef<T | null>(null);
  const reduced = usePrefersReducedMotion();

  useEffect(() => {
    const el = ref.current;
    if (!el) return;

    // Reduced motion: leave the SSR-visible state alone. No wipe.
    if (reduced) return;

    const io = new IntersectionObserver(
      (entries) => {
        for (const entry of entries) {
          if (entry.isIntersecting) {
            entry.target.classList.add("is-revealed");
            io.unobserve(entry.target);
          }
        }
      },
      { rootMargin: "-8% 0px -8% 0px", threshold: 0.12 },
    );
    io.observe(el);
    return () => io.disconnect();
  }, [reduced]);

  return ref;
}

"use client";

import { useEffect, useRef } from "react";
import "./styles.css";
import { inter, notoSansKR } from "./fonts";
import { useReveal } from "./hooks/useReveal";
import { usePrefersReducedMotion } from "./hooks/usePrefersReducedMotion";

export default function PrismPage() {
  const rootRef = useRef<HTMLDivElement | null>(null);
  const reduced = usePrefersReducedMotion();
  const revealRef = useReveal<HTMLDivElement>();

  useEffect(() => {
    rootRef.current?.classList.add("prism-js");
    window.parent?.postMessage({ type: "oneshot:ready", slug: "prism" }, "*");
  }, []);

  return (
    <div ref={rootRef} className={`${inter.variable} ${notoSansKR.variable} prism-root`}>
      <div ref={revealRef} className="prism-doc">
        <header className="prism-hero" data-reveal="">
          <p className="prism-kicker"><span lang="ko">빛의 굴절 스튜디오</span> · LIGHT REFRACTION STUDIO</p>
          <h1 className="prism-title">PRISM <span lang="ko">프리즘</span></h1>
          <p className="prism-sub" data-reveal=""><span lang="ko">유리가 빛을 굴절시킨다.</span> Glass refracts a beam.</p>
        </header>
        <section className="prism-body" data-reveal="">
          <p className="prism-body__text">
            <span lang="ko">이 엔트리는 갤러리 50개 로스터의 일부로, 순수 코드로 제작되었습니다. glass-futurism 패밀리의 세 번째 엔트리로, LUMEN NORD와 AURORA와 시각적으로 구별됩니다.</span>
            {" "}This entry is part of the gallery&rsquo;s 50-entry roster, built in pure code. The third glass-futurism entry, distinct from LUMEN NORD and AURORA.
          </p>
        </section>
        <footer className="prism-foot" data-reveal="">
          <p>© 2026 PRISM · MIT</p>
          <p><span lang="ko">코드로 그렸다</span> · drawn in code</p>
        </footer>
      </div>
    </div>
  );
}

/* prism — gallery entry 50-roster */
.prism-root {
  --prism-bg: #f8fafc;
  --prism-ink: #1e293b;
  --prism-accent: #06b6d4;
  position: relative;
  min-height: 100vh;
  background: var(--prism-bg);
  color: var(--prism-ink);
  font-family: var(--font-inter), var(--font-noto-sans-kr), sans-serif;
  font-size: clamp(15px, 0.5vw + 13px, 17px);
  line-height: 1.7;
  overflow-x: hidden;
}
.prism-root :lang(ko) { font-family: var(--font-noto-sans-kr), sans-serif; }
.prism-root ::selection { background: var(--prism-accent); color: var(--prism-bg); }
.prism-root :focus-visible { outline: 2px solid var(--prism-accent); outline-offset: 4px; }
.prism-js [data-reveal] {
  opacity: 0; transform: translateY(20px);
  transition: opacity 800ms cubic-bezier(0.16,1,0.3,1), transform 800ms cubic-bezier(0.16,1,0.3,1);
}
.prism-js [data-reveal].is-visible { opacity: 1; transform: none; }
@media (prefers-reduced-motion: reduce) {
  .prism-js [data-reveal] { opacity: 1; transform: none; transition: none; }
}
.prism-doc { position: relative; z-index: 1; }
.prism-hero { padding: clamp(80px,16vh,140px) clamp(20px,5vw,60px) clamp(40px,8vh,60px); }
.prism-kicker { font-size: 0.7rem; text-transform: uppercase; letter-spacing: 0.2em; color: var(--prism-accent); margin: 0 0 24px; }
.prism-title { font-weight: 700; font-size: clamp(3rem,10vw,6rem); line-height: 1; margin: 0 0 16px; }
.prism-title :lang(ko) { font-size: 0.5em; opacity: 0.7; }
.prism-sub { opacity: 0.6; margin: 0; }
.prism-body { padding: clamp(40px,8vh,80px) clamp(20px,5vw,60px); max-width: 680px; }
.prism-body__text { margin: 0; }
.prism-foot { padding: clamp(48px,10vh,80px) clamp(20px,5vw,60px); opacity: 0.5; font-size: 0.8rem; }
.prism-foot p { margin: 0 0 6px; }
